    tiles=[]
    for size in (3,2):
        for r in range(h-size+1):
            for c in range(w-size+1):
                v=grid[r][c]
                if v==0 or any(grid[y][x]!=v for y in range(r,r+size) for x in range(c,c+size)): continue
                # Interior of a framed tile: surrounding ring uses one other color.
                ring=[]
                for y in range(r-1,r+size+1):
                    for x in range(c-1,c+size+1):
                        if 0<=y<h and 0<=x<w and not (r<=y<r+size and c<=x<c+size): ring.append(grid[y][x])
                if ring and len(set(ring))==1 and ring[0] not in (0,v):
                    tiles.append((r,c,size,v))
    # deduplicate and retain only tiles on repeated regular arrangement
    unique={(r,c,s,v):(r,c,s,v) for r,c,s,v in tiles}
    tiles=list(unique.values())
    for r,c,s,v in tiles:
        for rr,cc,ss,vv in tiles:
            if vv!=v or (rr,cc)<=(r,c) or not (r==rr or c==cc): continue
            if s!=ss: continue
            # draw across blank gaps at corresponding interior rows/columns
            if r==rr:
                for y in range(r,r+s):
                    for x in range(c+s,cc):
                        if grid[y][x]==0: out[y][x]=v
            else:
                for x in range(c,c+s):
                    for y in range(r+s,rr):
                        if grid[y][x]==0: out[y][x]=v
