def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Each tile is a 5x5 framed block, with 3x3 uniform interior, arranged
    # every 7 cells. Connect equal unusual interior colors along aligned rows
    # or columns, filling only intervening zeros.
    tiles={}; values=[]
    for r in range(1,h,7):
        for c in range(1,w,7):
            if r+4>=h or c+4>=w: continue
            v=grid[r+1][c+1]
            if all(grid[y][x]==v for y in range(r+1,r+4) for x in range(c+1,c+4)):
                tiles[(r,c)]=v; values.append(v)
    from collections import Counter
    if not tiles: return out
    ordinary=Counter(values).most_common(1)[0][0]
    for (r,c),v in tiles.items():
        if v==ordinary: continue
        for (rr,cc),vv in tiles.items():
            if vv!=v or (rr,cc)<=(r,c) or not (r==rr or c==cc): continue
            if r==rr:
                for y in range(r+1,r+4):
                    for x in range(c+5,cc):
                        if grid[y][x]==0: out[y][x]=v
            else:
                for x in range(c+1,c+4):
                    for y in range(r+5,rr):
                        if grid[y][x]==0: out[y][x]=v
    return out
